<script setup>
import{onMounted,reactive,ref}from'vue';import api from '../services/api'
const users=ref([]),branches=ref([]),show=ref(false),error=ref(''),notice=ref('');const form=reactive({name:'',email:'',mobile:'',password:'',role:'manager',branch_id:''})
const load=async()=>{try{const[u,b]=await Promise.all([api.get('/admin/users'),api.get('/businesses')]);users.value=u.data.data;const business=b.data.data[0];branches.value=business?(await api.get(`/businesses/${business.id}/branches`)).data.data:[]}catch(e){error.value=e.response?.data?.message||'ব্যবহারকারী লোড করা যায়নি।'}}
const save=async()=>{error.value='';try{await api.post('/admin/users',{...form,branch_id:form.branch_id||null});Object.assign(form,{name:'',email:'',mobile:'',password:'',role:'manager',branch_id:''});show.value=false;notice.value='ব্যবহারকারী তৈরি হয়েছে।';load()}catch(e){error.value=e.response?.data?.message||Object.values(e.response?.data?.errors||{})[0]?.[0]||'সংরক্ষণ ব্যর্থ হয়েছে।'}}
const update=async user=>{error.value='';try{await api.put(`/admin/users/${user.id}`,{role:user.role,branch_id:user.branch_id||null,is_active:user.is_active});notice.value='পরিবর্তন সংরক্ষিত হয়েছে।';load()}catch(e){error.value=e.response?.data?.message||'আপডেট করা যায়নি।';load()}}
onMounted(load)
</script><template><section><div class="page-heading inline"><div><p class="eyebrow">ACCESS CONTROL</p><h2>ব্যবহারকারী ও রোল</h2><p>ব্যবহারকারী তৈরি, রোল, শাখা এবং অ্যাকাউন্ট অবস্থা পরিচালনা করুন।</p></div><button class="primary" @click="show=true">+ নতুন ব্যবহারকারী</button></div><p v-if="notice" class="success notice">✓ {{notice}}</p><p v-if="error" class="error">{{error}}</p><div v-if="show" class="page-card compact"><form class="form-grid" @submit.prevent="save"><label>নাম<input v-model="form.name" required /></label><label>ইমেইল<input v-model="form.email" type="email" required /></label><label>মোবাইল<input v-model="form.mobile" /></label><label>অস্থায়ী পাসওয়ার্ড<input v-model="form.password" type="password" minlength="8" required /></label><label>রোল<select v-model="form.role"><option value="owner">Owner</option><option value="manager">Manager</option><option value="accountant">Accountant</option><option value="salesperson">Salesperson</option></select></label><label>শাখা<select v-model="form.branch_id"><option value="">সব/কোনো শাখা নয়</option><option v-for="b in branches" :value="b.id">{{b.name}}</option></select></label><div class="full-width form-actions"><button type="button" class="secondary" @click="show=false">বাতিল</button><button class="primary">তৈরি করুন</button></div></form></div><div class="table-card"><table><thead><tr><th>ব্যবহারকারী</th><th>রোল</th><th>শাখা</th><th>অবস্থা</th><th></th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><strong>{{user.name}}</strong><small>{{user.email}} · {{user.mobile||'—'}}</small></td><td><select v-model="user.role"><option value="owner">Owner</option><option value="manager">Manager</option><option value="accountant">Accountant</option><option value="salesperson">Salesperson</option></select></td><td><select v-model="user.branch_id"><option :value="null">সব/কোনো শাখা নয়</option><option v-for="b in branches" :value="b.id">{{b.name}}</option></select></td><td><label class="switch"><input v-model="user.is_active" type="checkbox" /> {{user.is_active?'সক্রিয়':'নিষ্ক্রিয়'}}</label></td><td><button class="secondary small" @click="update(user)">সংরক্ষণ</button></td></tr></tbody></table></div></section></template>
